pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up an admin
        address admin = address(0x1234);
        c.setAdmin(admin, true);

        // Prank as admin and call newEmergencyOracle
        vm.prank(admin);
        c.newEmergencyOracle("test");

        // Get the deployed EmergencyOracle address from the event
        vm.expectEmit(true, true, false, false);
        emit NewEmergencyOracle(admin, address(0)); // dummy, we'll extract actual
        // We need to get the actual oracle address; since event is emitted, we can compute the address
        // Alternatively, we can use the fact that the EmergencyOracle is the last created contract
        // For simplicity, we'll deploy our own EmergencyOracle to get the address deterministically
        // But the simplest: we know the reference sets owner to admin, bug sets to address(0)
        // We'll assert that the owner of the new oracle is not address(0) for reference, is address(0) for bug
        // We'll just check that admin is not the owner in the buggy case by re-deploying?
        // Actually we can compute the address: 
        address newOracle = computeCreateAddress(address(c), vm.getNonce(address(c)) - 1);

        // Check the owner via a low-level call to the EmergencyOracle
        (bool success, bytes memory data) = newOracle.staticcall(abi.encodeWithSignature("owner()"));
        require(success, "owner call failed");
        address owner = abi.decode(data, (address));

        // In reference, owner == admin; in bug, owner == address(0)
        assertTrue(owner == admin, "Owner should be admin in reference");
    }
}

contract C {
    event NewEmergencyOracle(address owner, address newOracle);
    mapping(address => bool) public isAdmin;

    function setAdmin(address _admin, bool _isAdmin) external {
        isAdmin[_admin] = _isAdmin;
    }

    modifier onlyAdmin() {
        require(isAdmin[msg.sender], "Only admin can call address(this) function");
        _;
    }

    function newEmergencyOracle(string calldata description) external onlyAdmin {
        address newOracle = address(
            new EmergencyOracle(msg.sender, description)
        );
        emit NewEmergencyOracle(msg.sender, newOracle);
    }
}

contract EmergencyOracle is Ownable {
    uint256 public price;
    uint256 public roundId;
    string public description;
    bool public turnOn;

    event AnswerUpdated(int256 indexed current, uint256 indexed roundId, uint256 updatedAt);

    constructor(address _owner, string memory _description) Ownable() {
        transferOwnership(_owner);
        description = _description;
    }

    function getAssetPrice() external view returns (uint256) {
        require(turnOn, "the emergency oracle is close");
        return price;
    }

    function turnOnOracle() external onlyOwner {
        turnOn = true;
    }

    function turnOffOracle() external onlyOwner {
        turnOn = false;
    }

    function setAssetPrice(uint256 newPrice) external onlyOwner {
        price = newPrice;
        emit AnswerUpdated(int256(price), roundId, block.timestamp);
        roundId += 1;
    }
}

abstract contract Ownable {
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        _transferOwnership(msg.sender);
    }

    modifier onlyOwner() {
        require(owner() == msg.sender, "Ownable: caller is not the owner");
        _;
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function renounceOwnership() public onlyOwner {
        _transferOwnership(address(0));
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        _transferOwnership(newOwner);
    }

    function _transferOwnership(address newOwner) internal {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }
}

library SafeCast {
    function toInt256(uint256 value) internal pure returns (int256) {
        require(value <= uint256(type(int256).max), "SafeCast: value doesn't fit in an int256");
        return int256(value);
    }
}

